-- Recategorise components whose category contradicts the product they are.
--
-- Root cause: the DigiKey-era importer picked the FIRST keyword it found anywhere in the
-- product name, so accessory words won over the product noun: 'Micro Servo with 3-pin JST
-- PH 2mm Cable' became `cable`, 'Right Mecanum Wheel - 48mm ... TT Motor or Cross Axle'
-- became `inductor`, 'NEO Vortex Brushless Motor' became `connector`. The product type of a
-- name is its head noun, not its first keyword.
--
-- Scope: only names whose head noun is unambiguous after parentheses and qualifier clauses
-- ('with ...', ' - 48mm ...') are removed. Names that mention a part but are not that part
-- (kits, bundles, drivers, HATs, boards, extension cables, servo arms) are deliberately left
-- alone rather than guessed at. 142 rows, generated by categorise_head_noun.py; the review
-- list is /root/robopartpicker-seo/proposed-changes-2026-10-22.json.
--
-- The category is part of the part URL, so worker/services/seo.ts 301s the old path to the
-- canonical one (slug-only lookup); no component URL 404s as a result of this migration.

UPDATE components SET category = 'actuator', updated_at = '2026-10-22T05:00:00.000Z'
  WHERE category = 'cable' AND id IN ('c-18e026b07f8355df8d5a2868', 'c-468ab67e2696060bbbd317fc', 'c-4730b020803368e35f0a7096', 'c-7bde60d9eca92c1158c9b2a3', 'c-86f22ec61df3149282f0580c', 'c-88385c3d58cbd2ab4e9fd5c6', 'c-d57e59c60e850820e594d0ce', 'c-e96718691d2cd53df2c447c2');
